mapper.select:
SELECT * FROM (SELECT T.* FROM( SELECT #{effectFlag} effectFlag, ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1, ETR_ENTRUST_ADD.ASSET_TYPE_10 assetType10, ETR_ENTRUST_ADD.ASSET_TYPE_11 assetType11, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, decode(ETR_ENTRUST.ENTRUST_STATUS,'09',1,'02',2,'03',3,'04',4,'06',5,'05',6,'07',7) entrustStatusOrder, ETR_ENTRUST.ENTRUST_TYPE entrustType, ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.INV_MANAGER_ID invManagerId, su1.real_name invManagerName, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE finprodType2, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ('F07', 'F08') AND ETR_ENTRUST.PS IN ('03', '04', 'T56', 'T93', 'T94', 'T95', 'T96', 'T01') THEN ETR_ENTRUST_ADD.TERM_TYPE else(case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_MARKET_ID else ETR_ENTRUST_ADD.ASSET_TYPE_10 end) end finprodMarketId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN('03','04') THEN ETR_ENTRUST.STOCK_ID ELSE FIN_PRODUCT.FINPROD_ID END finprodId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN('03','04') AND ETR_ENTRUST.ENTRUST_TYPE NOT IN ('17', '18', '19', '20', '21') THEN ETR_ENTRUST.FINPROD_ID else (case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_ABBR else OPT_TARGET_INFO.TARGET_NAME end) end finprodAbbr, ETR_ENTRUST.PS Ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{IRS_TYPE} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12},#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',decode(ETR_ENTRUST.PS,'T03',ETR_ENTRUST.ENTRUST_AMT, NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0)),'F10',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM)) entrustAmt, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUSA.FINISH_AMT,0)) finishAmt, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.ENTRUST_DATE entrustDate, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, B.TRADER trader, B.realName realName, ETR_ENTRUST.REMARK remark, nvl(btm1.OUTPUT_VALUE_1,btm.busi_type) busiTypePosition, ssai.sec_acct_name secAcctId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F08' THEN DECODE( ETR_ENTRUST_ADD.SETTLE_SPREED, 1, '01', 2, '02', 3, '03') ELSE DECODE( ETR_ENTRUST_ADD.SETTLE_SPREED, 0, '01', 1, '02', 2, '03') END AS settleSpeed, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ('F01', 'F02', 'F03', 'F04', 'F05', 'F06', 'F09') THEN '' ELSE TO_CHAR(ETR_ENTRUST_ADD.TERM_DAYS) END AS termDays, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ('F05', 'F04', 'F03', 'F09', 'F06', 'F02') THEN round( 0, 4 ) ELSE nvl(round(decode(btm.busi_type,#{busiTypePosition02},decode(ETR_ENTRUST_ADD.CALCULATE_FIELD,'price',ETR_ENTRUST.PRICE,'exerYield',ETR_ENTRUST_ADD.EXER_YIELD*100,'matureYield',ETR_ENTRUST_ADD.MATURE_YIELD*100),#{busiTypePosition03},ETR_ENTRUST.PRICE,#{busiTypePosition05},ETR_ENTRUST.PRICE*100,''),4),ETR_ENTRUST.PRICE) END AS etrPrice,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND ETR_ENTRUST.ENTRUST_NUM != 0 then (CASE WHEN ETR_ENTRUST.ENTRUST_NUM != '0' THEN trunc(nvl(NVL(T7.FINISH_AMT, 0)+ NVL(T5.ENT_FINISH_AMT*100, 0),0)/(ETR_ENTRUST.ENTRUST_NUM*100),4)*100 ELSE 0 END ) when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND ETR_ENTRUST.ENTRUST_NUM = 0 then 0 when ETR_ENTRUST.ENTRUST_AMT = 0 then 0 else trunc(nvl(nvl(T7.FINISH_AMT, 0) + nvl(T5.ENT_FINISH_AMT, 0), 0) / ETR_ENTRUST.ENTRUST_AMT,4) * 100 end as exeProgress,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND ETR_ENTRUST.ENTRUST_NUM != 0 then (CASE WHEN ETR_ENTRUST.ENTRUST_NUM != '0' THEN trunc((NVL(CB.totalShareAmt,nvl(C2B.totalShareAmt,0))+NVL(T6.FINISH_AMT*100,0)+NVL(T5.FINISH_AMT*100,0))/(ETR_ENTRUST.ENTRUST_NUM*100),4)*100 ELSE 0 END ) when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND ETR_ENTRUST.ENTRUST_NUM = 0 then 0 WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ('F02', 'F05') THEN round(nvl(ETR_FINISH_STATUS_A.FINISH_AMT,0)/NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM),4)*100 WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ('F10', 'F08', 'F10', 'F04', 'F03', 'F09', 'F06') THEN round(NVL(T10.FINISH_AMT,0)/ NVL(ETR_ENTRUST.ENTRUST_NUM, ETR_ENTRUST.ENTRUST_AMT),4)*100 when (ETR_ENTRUST.ENTRUST_AMT = 0 OR ETR_ENTRUST.ENTRUST_AMT IS NULL ) then 0 else trunc((nvl(C.totalShareAmt, nvl(C2.FPRICE_AMT, 0)) + nvl(T6.FINISH_AMT, 0)+NVL(T5.FINISH_AMT,0)) / ETR_ENTRUST.ENTRUST_AMT, 4) * 100 end as dealProgress,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then (NVL(T7.FINISH_AMT,0)+NVL(T5.ENT_FINISH_AMT*100,0))/10000 else round((NVL(T7.FINISH_AMT, 0) + NVL(T5.ENT_FINISH_AMT, 0))/10000,2) end as execFinishAmt,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then NVL(ETR_ENTRUST.ENTRUST_NUM, 0)/100 - NVL(T7.FINISH_AMT,0)/10000 - NVL(T5.ENT_FINISH_AMT,0)/100 else round((NVL(ETR_ENTRUST.ENTRUST_AMT, 0) - NVL(T7.FINISH_AMT, 0) - NVL(T5.ENT_FINISH_AMT, 0))/10000,2) end as execRemainderAmt,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then ROUND(NVL(CB.totalShareAmt,nvl(C2B.totalShareAmt,0))+NVL(T6.FINISH_AMT*100,0))/10000 else ROUND((NVL(C.totalShareAmt, nvl(C2.FPRICE_AMT, 0)) + NVL(T6.FINISH_AMT, 0))/10000,2) end as transFinishAmt,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then NVL(ETR_ENTRUST.ENTRUST_NUM, 0)/100 - ROUND(NVL(CB.totalShareAmt,nvl(C2B.totalShareAmt,0))+NVL(T6.FINISH_AMT*100,0))/10000 else ROUND((NVL(ETR_ENTRUST.ENTRUST_AMT, 0) - NVL(C.totalShareAmt, nvl(C2.FPRICE_AMT, 0)) + NVL(T6.FINISH_AMT, 0))/10000,2) end as transRemainderAmt, to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME,'hh24:mi:ss') transmitTime, to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME,'hh24:mi') transmitTimeSer, ETR_ENTRUST_ADD.CALCULATE_FIELD FROM (SELECT * FROM ETR_ENTRUST ORDER BY ENTRUST_DATE DESC) ETR_ENTRUST LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT listagg(TRADER, ',') within group ( order by TRADER ) TRADER, listagg(REAL_NAME, ',') within group(order by TRADER) realName, ENTRUST_ID as ENTRUST_ID FROM ETR_DISTRIBUTE LEFT JOIN SYS_USER ON ETR_DISTRIBUTE.TRADER = SYS_USER.USER_NAME GROUP BY ENTRUST_ID)B ON B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS WHERE ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) ETR_FINISH_STATUSA ON ETR_FINISH_STATUSA.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN OPT_TARGET_INFO ON ETR_ENTRUST_ADD.ASSET_TYPE_10 = OPT_TARGET_INFO.TARGET_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID LEFT JOIN (SELECT listagg(BID_PRICE, ',') within group (order by BID_PRICE) BID_PRICE, ENTRUST_ID as ENTRUST_ID FROM ETR_ENTRUST_BID_PRICE GROUP BY ENTRUST_ID) EEBP ON EEBP.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) as FINISH_AMT,SUM(Ent_Finish_Amt) as Ent_Finish_Amt FROM ETR_FINISH_STATUS where ENTRUST_ID = TRADE_ID GROUP BY ENTRUST_ID) T5 ON ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T7 ON ETR_ENTRUST.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN(SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS INNER JOIN (SELECT DISTINCT T3.TRADE_ID FROM TRDQUTO_MATCH_INFO T1 INNER JOIN REG_FIN_PRODUCT_DEAL_TOTAL T2 ON T1.PRE_TRADE_ID = T2.TOTLE_TRADE_ID INNER JOIN TRD_PRODUCT_DEAL T3 ON T3.TOTLE_TRADE_ID = T1.TRD_ID WHERE TRD_CONF_STATUS = '1') REG ON REG.TRADE_ID = ETR_FINISH_STATUS.TRADE_ID GROUP BY ENTRUST_ID) T6 ON ETR_ENTRUST.ENTRUST_ID = T6.ENTRUST_ID LEFT JOIN (SELECT iqer.ENTRUST_ID, SUM(nvl(iqer.FPRICE_AMT, 0)) totalShareAmt FROM IBU_QUOTE_ETR_RE iqer /*质押式回购银行间报价*/ where QUOTE_ID in (select QUOTE_ID from IBU_QUOTE_CREP where TRADE_STATUS = '07') GROUP BY iqer.ENTRUST_ID) C /*质押式回购银行间报价 按指令代码汇总 交易份额，债券数量等*/ ON C.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT iqer.ENTRUST_ID, iqer.FPRICE_AMT FROM IBU_QUOTE_ETR_RE iqer /*质押式回购银行间报价*/ where QUOTE_ID in (select QUOTE_ID from IBU_QUOTE_CREP where TRADE_STATUS = '07')) C2/*质押式回购银行间报价*/ ON C2.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT C.ENTRUST_ID, SUM(nvl(C.SHARE_AMT, 0)) * 100 totalShareAmt FROM IBU_QUOTE_BOND A LEFT JOIN IBU_QUOTE_BOND_DET B ON A.QUOTE_ID = B.QUOTE_ID LEFT JOIN IBU_QUOTE_ETR_RE C ON A.QUOTE_ID = C.QUOTE_ID WHERE B.TRADE_STATUS = '07' GROUP BY C.ENTRUST_ID) CB ON CB.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT A.ENTRUST_ID, nvl(A.SHARE_AMT, 0) * 100 totalShareAmt FROM IBU_QUOTE_BOND A LEFT JOIN IBU_QUOTE_BOND_DET B ON A.QUOTE_ID = B.QUOTE_ID WHERE B.TRADE_STATUS = '07') C2B ON C2B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON ETR_ENTRUST_ADD.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN SYS_USER su1 ON ETR_ENTRUST.INV_MANAGER_ID = su1.USER_NAME LEFT JOIN (select INPUT_VALUE_1 as Finprod_Type_Tg,INPUT_VALUE_2 as ps,OUTPUT_VALUE_1 as busi_type from FIN_PRODUCT_TYPE_CONFIG where CONFIG_TYPE='BUSI_TYPE_MAPPING') btm ON ETR_ENTRUST_ADD.ASSET_TYPE = btm.Finprod_Type_Tg AND ETR_ENTRUST.Ps = btm.ps LEFT JOIN FIN_PRODUCT_TYPE_CONFIG btm1 ON ( ETR_ENTRUST.FINPROD_TYPE2 = btm1.INPUT_VALUE_2 OR btm1.INPUT_VALUE_2 IS NULL) AND ( ETR_ENTRUST.Ps = btm1.INPUT_VALUE_3 OR btm1.INPUT_VALUE_3 IS NULL) AND ( ETR_ENTRUST.TRADE_PLAT = btm1.INPUT_VALUE_1 OR btm1.INPUT_VALUE_1 IS NULL) LEFT JOIN (SELECT ENTRUST_ID, SUM(NVL(FINISH_AMT,0)) FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T10 ON ETR_ENTRUST.ENTRUST_ID = T10.ENTRUST_ID left join (select ENTRUST_ID,sum(nvl(FINISH_AMT,0)) as FINISH_AMT from ETR_FINISH_STATUS where ENTRUST_ID != TRADE_ID group by ENTRUST_ID) ETR_FINISH_STATUS_A on ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
AND ETR_ENTRUST.ENTRUST_STATUS IN(#{entrustAwait},#{entrustDistribute},#{entrustReceive},#{entrustUntread},#{entrustClose},#{entrustReturn},#{entrustRecall})
AND ETR_ENTRUST.ENTRUST_STATUS IN
#{item}
AND ETR_ENTRUST.PORTFOLIO_ID IN(
#{item}
)
AND (case
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) then ETR_ENTRUST_ADD.BUSI_PS
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) then ETR_ENTRUST_ADD.BUSI_PS
else ETR_ENTRUST.PS end) =#{ps}
AND ETR_ENTRUST_ADD.ASSET_TYPE = #{finprodType2}
AND btm.busi_type = #{busiTypePosition}
AND FIN_PRODUCT.FINPROD_MARKET_ID IN(
#{item}
)
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND ETR_ENTRUST_ADD.SETTLE_SPREED = #{settleSpeed}
AND ETR_ENTRUST_ADD.SEC_ACCT_ID IN(
#{item}
)
AND ETR_ENTRUST.ENTRUST_ID LIKE concat(concat('%',#{entrustId,jdbcType=VARCHAR}),'%')
AND ETR_ENTRUST.INV_MANAGER_ID IN(
#{item}
)
AND to_char(ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') >= #{entrustStartDate} AND to_char(ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') <= #{entrustEndDate}
AND ETR_ENTRUST.CCY = #{ccy}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
union all SELECT #{effectFlag} effectFlag, ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1, ETR_ENTRUST_ADD.ASSET_TYPE_10 assetType10, ETR_ENTRUST_ADD.ASSET_TYPE_11 assetType11, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, decode(ETR_ENTRUST.ENTRUST_STATUS,'09',1,'02',2,'03',3,'04',4,'06',5,'05',6,'07',7) entrustStatusOrder, ETR_ENTRUST.ENTRUST_TYPE entrustType, ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.INV_MANAGER_ID invManagerId, su2.real_name invManagerName, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST.FINPROD_TYPE2 finprodType2, ETR_ENTRUST.FINPROD_ID finprodMarketId, FIN_PRODUCT.FINPROD_ID finprodId, ETR_ENTRUST_ADD.ASSET_TYPE_11 finprodAbbr, ETR_ENTRUST.PS Ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{IRS_TYPE} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12},#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',decode(ETR_ENTRUST.PS,'T03',ETR_ENTRUST.ENTRUST_AMT, NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0)),'F10',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM)) entrustAmt, decode(ETR_ENTRUST_ADD.CONTRACT_RESULT,'已签署完毕',ETR_ENTRUST.ENTRUST_AMT,0) finishAmt, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.ENTRUST_DATE entrustDate, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, B.TRADER trader, B.realName realName, ETR_ENTRUST.REMARK remark, nvl(btm1.OUTPUT_VALUE_1,btm.busi_type) busiTypePosition, ssai.sec_acct_name secAcctId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE = 'F08' THEN DECODE( ETR_ENTRUST_ADD.SETTLE_SPREED, 1, '01', 2, '02', 3, '03') ELSE DECODE( ETR_ENTRUST_ADD.SETTLE_SPREED, 0, '01', 1, '02', 2, '03') END AS settleSpeed, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ('F01', 'F02', 'F03', 'F04', 'F05', 'F06', 'F09') THEN '' ELSE TO_CHAR(ETR_ENTRUST_ADD.TERM_DAYS) END AS termDays, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ('F05', 'F04', 'F03', 'F09', 'F06', 'F02') THEN round( 0, 4 ) ELSE nvl(round(decode(btm.busi_type,#{busiTypePosition02},decode(ETR_ENTRUST_ADD.CALCULATE_FIELD,'price',ETR_ENTRUST.PRICE,'exerYield',ETR_ENTRUST_ADD.EXER_YIELD*100,'matureYield',ETR_ENTRUST_ADD.MATURE_YIELD*100),#{busiTypePosition03},ETR_ENTRUST.PRICE,#{busiTypePosition05},ETR_ENTRUST.PRICE*100,''),4),ETR_ENTRUST.PRICE) END AS etrPrice, case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND ETR_ENTRUST.ENTRUST_NUM != 0 then trunc(nvl(NVL(T7.FINISH_AMT, 0)+ NVL(T5.ENT_FINISH_AMT*100, 0),0)/(ETR_ENTRUST.ENTRUST_NUM*100),4)*100 when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND ETR_ENTRUST.ENTRUST_NUM = 0 then 0 when ETR_ENTRUST.ENTRUST_AMT = 0 then 0 else trunc(nvl(nvl(T7.FINISH_AMT, 0) + nvl(T5.ENT_FINISH_AMT, 0), 0) / ETR_ENTRUST.ENTRUST_AMT,4) * 100 end as exeProgress,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND ETR_ENTRUST.ENTRUST_NUM != 0 then trunc((NVL(CB.totalShareAmt,nvl(C2B.totalShareAmt,0))+NVL(T6.FINISH_AMT*100,0)+NVL(T5.FINISH_AMT*100,0))/(ETR_ENTRUST.ENTRUST_NUM*100),4)*100 when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' AND ETR_ENTRUST.ENTRUST_NUM = 0 then 0 WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ('F02', 'F05') THEN round(nvl(ETR_FINISH_STATUS_A.FINISH_AMT,0)/NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM),4)*100 WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ('F10', 'F08', 'F10', 'F04', 'F03', 'F09', 'F06') THEN round(NVL(T10.FINISH_AMT,0)/ NVL(ETR_ENTRUST.ENTRUST_NUM, ETR_ENTRUST.ENTRUST_AMT),4)*100 when (ETR_ENTRUST.ENTRUST_AMT = 0 OR ETR_ENTRUST.ENTRUST_AMT IS NULL ) then 0 else trunc((nvl(C.totalShareAmt, nvl(C2.FPRICE_AMT, 0)) + nvl(T6.FINISH_AMT, 0)+NVL(T5.FINISH_AMT,0)) / ETR_ENTRUST.ENTRUST_AMT, 4) * 100 end as dealProgress,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then (NVL(T7.FINISH_AMT,0)+NVL(T5.ENT_FINISH_AMT*100,0))/10000 else round((NVL(T7.FINISH_AMT, 0) + NVL(T5.ENT_FINISH_AMT, 0))/10000,2) end as execFinishAmt,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then NVL(ETR_ENTRUST.ENTRUST_NUM, 0)/100 - NVL(T7.FINISH_AMT,0)/10000 - NVL(T5.ENT_FINISH_AMT,0)/100 else round((NVL(ETR_ENTRUST.ENTRUST_AMT, 0) - NVL(T7.FINISH_AMT, 0) - NVL(T5.ENT_FINISH_AMT, 0))/10000,2) end as execRemainderAmt,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then ROUND(NVL(CB.totalShareAmt,nvl(C2B.totalShareAmt,0))+NVL(T6.FINISH_AMT*100,0))/10000 else ROUND((NVL(C.totalShareAmt, nvl(C2.FPRICE_AMT, 0)) + NVL(T6.FINISH_AMT, 0))/10000,2) end as transFinishAmt,
case when ETR_ENTRUST_ADD.ASSET_TYPE = 'F01' then NVL(ETR_ENTRUST.ENTRUST_NUM, 0)/100 - ROUND(NVL(CB.totalShareAmt,nvl(C2B.totalShareAmt,0))+NVL(T6.FINISH_AMT*100,0))/10000 else ROUND((NVL(ETR_ENTRUST.ENTRUST_AMT, 0) - NVL(C.totalShareAmt, nvl(C2.FPRICE_AMT, 0)) + NVL(T6.FINISH_AMT, 0))/10000,2) end as transRemainderAmt, to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME,'hh24:mi:ss') transmitTime, to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME,'hh24:mi') transmitTimeSer, ETR_ENTRUST_ADD.CALCULATE_FIELD FROM (SELECT * FROM ETR_ENTRUST ORDER BY ENTRUST_DATE DESC) ETR_ENTRUST LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT listagg(TRADER, ',') within group ( order by TRADER ) TRADER, listagg(REAL_NAME, ',') within group(order by TRADER) realName, ENTRUST_ID as ENTRUST_ID FROM ETR_DISTRIBUTE LEFT JOIN SYS_USER ON ETR_DISTRIBUTE.TRADER = SYS_USER.USER_NAME GROUP BY ENTRUST_ID)B ON B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS WHERE ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) ETR_FINISH_STATUSA ON ETR_FINISH_STATUSA.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN (SELECT listagg(BID_PRICE, ',') within group (order by BID_PRICE) BID_PRICE, ENTRUST_ID as ENTRUST_ID FROM ETR_ENTRUST_BID_PRICE GROUP BY ENTRUST_ID) EEBP ON EEBP.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) as FINISH_AMT,SUM(Ent_Finish_Amt) as Ent_Finish_Amt FROM ETR_FINISH_STATUS where ENTRUST_ID = TRADE_ID GROUP BY ENTRUST_ID) T5 ON ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T7 ON ETR_ENTRUST.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN(SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS INNER JOIN (SELECT DISTINCT T3.TRADE_ID FROM TRDQUTO_MATCH_INFO T1 INNER JOIN REG_FIN_PRODUCT_DEAL_TOTAL T2 ON T1.PRE_TRADE_ID = T2.TOTLE_TRADE_ID INNER JOIN TRD_PRODUCT_DEAL T3 ON T3.TOTLE_TRADE_ID = T1.TRD_ID WHERE TRD_CONF_STATUS = '1') REG ON REG.TRADE_ID = ETR_FINISH_STATUS.TRADE_ID GROUP BY ENTRUST_ID) T6 ON ETR_ENTRUST.ENTRUST_ID = T6.ENTRUST_ID LEFT JOIN (SELECT iqer.ENTRUST_ID, SUM(nvl(iqer.FPRICE_AMT, 0)) totalShareAmt FROM IBU_QUOTE_ETR_RE iqer /*质押式回购银行间报价*/ where QUOTE_ID in (select QUOTE_ID from IBU_QUOTE_CREP where TRADE_STATUS = '07') GROUP BY iqer.ENTRUST_ID) C /*质押式回购银行间报价 按指令代码汇总 交易份额，债券数量等*/ ON C.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT iqer.ENTRUST_ID, iqer.FPRICE_AMT FROM IBU_QUOTE_ETR_RE iqer /*质押式回购银行间报价*/ where QUOTE_ID in (select QUOTE_ID from IBU_QUOTE_CREP where TRADE_STATUS = '07')) C2/*质押式回购银行间报价*/ ON C2.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT C.ENTRUST_ID, SUM(nvl(C.SHARE_AMT, 0)) * 100 totalShareAmt FROM IBU_QUOTE_BOND A LEFT JOIN IBU_QUOTE_BOND_DET B ON A.QUOTE_ID = B.QUOTE_ID LEFT JOIN IBU_QUOTE_ETR_RE C ON A.QUOTE_ID = C.QUOTE_ID WHERE B.TRADE_STATUS = '07' GROUP BY C.ENTRUST_ID) CB ON CB.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT A.ENTRUST_ID, nvl(A.SHARE_AMT, 0) * 100 totalShareAmt FROM IBU_QUOTE_BOND A LEFT JOIN IBU_QUOTE_BOND_DET B ON A.QUOTE_ID = B.QUOTE_ID WHERE B.TRADE_STATUS = '07') C2B ON C2B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON ETR_ENTRUST_ADD.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN SYS_USER su2 ON ETR_ENTRUST.INV_MANAGER_ID = su2.USER_NAME LEFT JOIN (select INPUT_VALUE_1 as Finprod_Type_Tg,INPUT_VALUE_2 as ps,OUTPUT_VALUE_1 as busi_type from FIN_PRODUCT_TYPE_CONFIG where CONFIG_TYPE='BUSI_TYPE_MAPPING') btm ON ETR_ENTRUST.FINPROD_TYPE2 = btm.Finprod_Type_Tg AND ETR_ENTRUST.Ps = btm.ps LEFT JOIN FIN_PRODUCT_TYPE_CONFIG btm1 ON ( ETR_ENTRUST.FINPROD_TYPE2 = btm1.INPUT_VALUE_2 OR btm1.INPUT_VALUE_2 IS NULL) AND ( ETR_ENTRUST.Ps = btm1.INPUT_VALUE_3 OR btm1.INPUT_VALUE_3 IS NULL) AND ( ETR_ENTRUST.TRADE_PLAT = btm1.INPUT_VALUE_1 OR btm1.INPUT_VALUE_1 IS NULL) LEFT JOIN (SELECT ENTRUST_ID, SUM(NVL(FINISH_AMT,0)) FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T10 ON ETR_ENTRUST.ENTRUST_ID = T10.ENTRUST_ID left join (select ENTRUST_ID,sum(nvl(FINISH_AMT,0)) as FINISH_AMT from ETR_FINISH_STATUS where ENTRUST_ID != TRADE_ID group by ENTRUST_ID) ETR_FINISH_STATUS_A on ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
AND ETR_ENTRUST.FINPROD_TYPE2 = 'F36' AND ETR_ENTRUST.ENTRUST_STATUS IN(#{entrustAwait},#{entrustDistribute},#{entrustReceive},#{entrustUntread},#{entrustClose},#{entrustReturn},#{entrustRecall})
AND ETR_ENTRUST.ENTRUST_STATUS IN
#{item}
AND ETR_ENTRUST.PORTFOLIO_ID IN(
#{item}
)
AND (case
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) then ETR_ENTRUST_ADD.BUSI_PS
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) then ETR_ENTRUST_ADD.BUSI_PS
else ETR_ENTRUST.PS end) =#{ps}
AND ETR_ENTRUST_ADD.ASSET_TYPE = #{finprodType2}
AND btm.busi_type = #{busiTypePosition}
AND FIN_PRODUCT.FINPROD_MARKET_ID IN(
#{item}
)
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND ETR_ENTRUST_ADD.SETTLE_SPREED = #{settleSpeed}
AND ETR_ENTRUST_ADD.SEC_ACCT_ID IN(
#{item}
)
AND ETR_ENTRUST.ENTRUST_ID LIKE concat(concat('%',#{entrustId,jdbcType=VARCHAR}),'%')
AND ETR_ENTRUST.INV_MANAGER_ID IN(
#{item}
)
AND to_char(ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') >= #{entrustStartDate} AND to_char(ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') <= #{entrustEndDate}
AND ETR_ENTRUST.CCY = #{ccy} ) t left join SYS_DATADICT_LIST sdl on sdl.DICT_CODE='STATUS_VALID' and t.effectFlag=sdl.ITEM_CODE left join SYS_DATADICT_LIST sdl1 on sdl1.DICT_CODE='ENTRUST_STATUS' and t.entrustStatus=sdl1.ITEM_CODE left join SYS_DATADICT_LIST sdl2 on sdl2.DICT_CODE='PINAN_ASSET_TYPE' and t.finprodType2=sdl2.ITEM_CODE left join SYS_DATADICT_LIST sdl3 on sdl3.DICT_CODE='BUSI_TYPE_POSITION' and t.busiTypePosition=sdl3.ITEM_CODE left join SYS_DATADICT_LIST sdl4 on sdl4.DICT_CODE='PS' and t.PS=sdl4.ITEM_CODE left join SYS_DATADICT_LIST sdl5 on sdl5.DICT_CODE='TRADE_MARKET' and t.tradeMarket=sdl5.ITEM_CODE left join SYS_DATADICT_LIST sdl6 on sdl6.DICT_CODE='ACCOUNT_SPEED' and t.settleSpeed=sdl6.ITEM_CODE left join SYS_DATADICT_LIST sdl7 on sdl7.DICT_CODE='CCY' and t.ccy=sdl7.ITEM_CODE
order by t.entrustStatusOrder,t.transmitTime,t.finprodType2,t.finprodMarketId,t.ps)
order by ${sort} ${direction}

if.where:
(sdl.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl1.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl2.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl3.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl4.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl5.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl6.ITEM_VALUE like '%' || #{search} || '%'
    OR sdl7.ITEM_VALUE like '%' || #{search} || '%'
    OR t.entrustId like '%' || #{search} || '%'
    OR t.invManagerId like '%' || #{search} || '%'
    OR t.invManagerName like '%' || #{search} || '%'
    OR t.realName like '%' || #{search} || '%'
    OR t.trader like '%' || #{search} || '%'
    OR t.portfolioId like '%' || #{search} || '%'
    OR t.portfolioName like '%' || #{search} || '%'
    OR t.finprodMarketId like '%' || #{search} || '%'
    OR t.finprodAbbr like '%' || #{search} || '%'
    OR t.remark like '%' || #{search} || '%'
    OR t.secAcctId like '%' || #{search} || '%'
    OR t.entrustAmt||'' = #{search}
    OR t.etrPrice||'' = #{search}
    OR t.termDays||'' = #{search}
    OR t.exeProgress||'' = #{search}
    OR t.dealProgress||'' = #{search}
    OR TO_CHAR(t.entrustDate,'yyyy-MM-dd') ||''= #{search}
    OR TO_CHAR(t.entrustDate,'yyyy-MM-dd') ||''= #{year}||'-'||#{search}
    OR replace(TO_CHAR(t.entrustDate,'yyyy-MM-dd'),'-','/')=#{search}
    OR replace(TO_CHAR(t.entrustDate,'yyyy-MM-dd'),'-','/')=#{year}||'/'||#{search}
    OR t.transmitTime = #{search}
    OR t.transmitTimeSer = #{search}
)

mapper.select:
SELECT DISTINCT SYS_USER.USER_NAME userName, SYS_USER.REAL_NAME realName FROM SYS_USER INNER JOIN SYS_USER_ROLE ON SYS_USER.USER_NAME = SYS_USER_ROLE.USER_ID INNER JOIN SYS_ROLE ON SYS_USER_ROLE.ROLE_ID = SYS_ROLE.ROLE_ID
AND SYS_ROLE.ROLE_POS IN(
#{item}
)
AND (SYS_USER.USER_NAME like concat(concat('%', #{dealers,jdbcType=VARCHAR}),'%') OR SYS_USER.REAL_NAME like concat(concat('%', #{dealers,jdbcType=VARCHAR}),'%'))

SELECT to_char(ete.entrust_date,'yyyy-MM-dd') entrustDate, CASE WHEN eted.ASSET_TYPE IN ( 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'IRS_TYPE' AND ITEM_CODE = eted.BUSI_PS ) WHEN eted.ASSET_TYPE IN ( 'F08', 'F10', 'F12', 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'BACK_LEND_DIRECTION' AND ITEM_CODE = eted.BUSI_PS ) ELSE ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'PS' AND ITEM_CODE = ete.PS ) END AS otherPs, mci2.CALENDAR_NAME calendarName, eted.ASSET_TYPE1 assetType1, eted.ASSET_TYPE_10 assetType10, eted.ASSET_TYPE_11 assetType11, ete.PRICE price, ssai.sec_acct_name secAcctId, fpa.TRM_FUND_TYPE trmFundType, fpa.TRM_FUND_ABBR trmFundAbbr, to_char( eted.VDATE, 'yyyy-MM-dd' ) vDate, to_char( eted.MDATE , 'yyyy-MM-dd' ) mDate, ete.portfolio_id portfolioId, pp.portfolio_name portfolioName, fp.finprod_market_id finprodMarketId, fp.finprod_abbr finprodAbbr, ete.trade_market tradeMarket, ete.ps ps, ete.ccy ccy, ete.remark remark, ete.ENTRUST_NUM shareNum, ete.entrust_amt shareAmt, eted.term_type termType, decode( eted.ASSET_TYPE, 'F01', '', 'F07', eted.TERM_DAYS, 'F10', eted.TERM_DAYS, 'F12', eted.TERM_DAYS, 'F16', eted.TERM_DAYS, eted.TERM_DAYS ) termDays, ete.PRICE * 100 rate FROM ETR_ENTRUST ete INNER JOIN ETR_ENTRUST_ADD eted ON ete.entrust_id = eted.entrust_id LEFT JOIN PTL_PORTFOLIO pp ON ete.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON ete.finprod_id = fp.finprod_id LEFT JOIN PTL_SEC_STOCK pss ON pss.pledge_stock_id = eted.pledge_stock_id AND ete.portfolio_id = pss.portfolio_id LEFT JOIN MST_CALENDAR_INFO mci2 ON mci2.CALENDAR_ID = ete.CALENDAR_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON eted.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT_ADD fpa ON ete.finprod_id = fpa.finprod_id WHERE ete.entrust_id = #{entrustId}
union
SELECT to_char(ete.entrust_date,'yyyy-MM-dd') entrustDate, CASE WHEN eted.ASSET_TYPE IN ( 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'IRS_TYPE' AND ITEM_CODE = eted.BUSI_PS ) WHEN eted.ASSET_TYPE IN ( 'F08', 'F10', 'F12', 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'BACK_LEND_DIRECTION' AND ITEM_CODE = eted.BUSI_PS ) ELSE ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'PS' AND ITEM_CODE = ete.PS ) END AS otherPs, mci2.CALENDAR_NAME calendarName, eted.ASSET_TYPE1 assetType1, eted.ASSET_TYPE_10 assetType10, eted.ASSET_TYPE_11 assetType11, ete.PRICE price, ssai.sec_acct_name secAcctId, fpa.TRM_FUND_TYPE trmFundType, fpa.TRM_FUND_ABBR trmFundAbbr, to_char( eted.VDATE, 'yyyy-MM-dd' ) vDate, to_char( eted.MDATE , 'yyyy-MM-dd' ) mDate, ete.portfolio_id portfolioId, pp.portfolio_name portfolioName, fp.finprod_market_id finprodMarketId, fp.finprod_abbr finprodAbbr, ete.trade_market tradeMarket, ete.ps ps, ete.ccy ccy, ete.remark remark, ete.ENTRUST_NUM shareNum, ete.entrust_amt shareAmt, eted.term_type termType, decode( eted.ASSET_TYPE, 'F01', '', 'F07', eted.TERM_DAYS, 'F10', eted.TERM_DAYS, 'F12', eted.TERM_DAYS, 'F16', eted.TERM_DAYS, eted.TERM_DAYS ) termDays, ete.PRICE * 100 rate FROM WFL_ETR_ENTRUST ete INNER JOIN WFL_ETR_ENTRUST_ADD eted ON ete.entrust_id = eted.entrust_id LEFT JOIN PTL_PORTFOLIO pp ON ete.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON ete.finprod_id = fp.finprod_id LEFT JOIN PTL_SEC_STOCK pss ON pss.pledge_stock_id = eted.pledge_stock_id AND ete.portfolio_id = pss.portfolio_id LEFT JOIN MST_CALENDAR_INFO mci2 ON mci2.CALENDAR_ID = ete.CALENDAR_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON eted.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT_ADD fpa ON ete.finprod_id = fpa.finprod_id WHERE ete.entrust_id = #{entrustId}

SELECT to_char(ete.entrust_date,'yyyy-MM-dd') entrustDate, CASE WHEN eted.ASSET_TYPE IN ( 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'IRS_TYPE' AND ITEM_CODE = eted.BUSI_PS ) WHEN eted.ASSET_TYPE IN ( 'F08', 'F10', 'F12', 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'BACK_LEND_DIRECTION' AND ITEM_CODE = eted.BUSI_PS ) ELSE ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'PS' AND ITEM_CODE = ete.PS ) END AS otherPs, T4.TARGET_FINPROD_ID targetFinprodId, NVL ( T5.FINPROD_ABBR, T5.FINPROD_NAME ) targetFinprodName, mci2.CALENDAR_NAME calendarName, to_char( eted.VDATE, 'yyyy-MM-dd' ) vDate, to_char( eted.MDATE , 'yyyy-MM-dd' ) mDate, eted.MIN_AMT minAmt, eted.ASSET_TYPE1 paBussType, ete.portfolio_id portfolioId, pp.portfolio_name portfolioName, ete.inv_aim busiModel, fp.finprod_market_id finprodMarketId, fp.finprod_abbr finprodAbbr, ete.trade_market tradeMarket, ete.ps ps, DECODE(eted.SETTLE_SPREED,0,'01',1,'02','2','03') settleSpeed, ete.price_model priceModel, ssai.sec_acct_name secAcctId, ete.ccy ccy, decode( eted.ASSET_TYPE, 'F01', NVL( ete.ENTRUST_NUM * 100, 0 ), 'F10', NVL( ete.ENTRUST_NUM * 100, 0 ), NVL( ete.ENTRUST_AMT, ete.ENTRUST_NUM )) shareNum, eted.our_ent_num/100 entrustOwnNum, eted.lendin_ent_num integrateSecAmount, ete.price unitPrice, eted.full_price allPrice, eted.mature_yield*100 matureYield, eted.exer_yield*100 exerYield, eted.full_price*ete.entrust_num fpriceAmt, ete.remark remark, mci.CUSTOMER_NAME mainConsignee, to_char(eted.payment_date,'yyyy-MM-dd') paymentDate, to_char(eted.listing_date,'yyyy-MM-dd') listingDate, ete.entrust_num entrustNum, ete.entrust_amt entrustAmt, eted.deal_mode dealMode, eted.term_type termType, decode( eted.ASSET_TYPE, 'F01', '', 'F07', eted.TERM_DAYS, 'F10', eted.TERM_DAYS, 'F12', eted.TERM_DAYS, 'F16', eted.TERM_DAYS, eted.TERM_DAYS ) termDays, to_char(eted.MDATE,'yyyy-MM-dd') || ' - ' || to_char(eted.MDATE2,'yyyy-MM-dd') as dueDate, eted.TERM_DAYS repoTerm, eted.FIRST_UNIT_CPRICE || ' - ' || eted.FIRST_UNIT_CPRICE2 firstprice, pss.pledge_stock_name pledgeStockName, fp.Is_Right isRight, ete.PRICE * 100 rate FROM ETR_ENTRUST ete INNER JOIN ETR_ENTRUST_ADD eted ON ete.entrust_id = eted.entrust_id LEFT JOIN PTL_PORTFOLIO pp ON ete.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON ete.finprod_id = fp.finprod_id LEFT JOIN PTL_SEC_STOCK pss ON pss.pledge_stock_id = eted.pledge_stock_id AND ete.portfolio_id = pss.portfolio_id LEFT JOIN MST_CUSTOMER_INFO mci ON mci.CUSTOMER_ID = eted.main_consignee AND mci.IS_SALER = #{YESORNO_YES, jdbcType = VARCHAR} LEFT JOIN STL_SEC_ACCT_INFO ssai ON eted.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN ETR_TARGET T4 ON ete.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN FIN_PRODUCT T5 ON T4.TARGET_FINPROD_ID = T5.FINPROD_ID LEFT JOIN MST_CALENDAR_INFO mci2 ON mci2.CALENDAR_ID = ete.CALENDAR_ID WHERE ete.entrust_id = #{entrustId}
union
SELECT to_char(ete.entrust_date,'yyyy-MM-dd') entrustDate, CASE WHEN eted.ASSET_TYPE IN ( 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'IRS_TYPE' AND ITEM_CODE = eted.BUSI_PS ) WHEN eted.ASSET_TYPE IN ( 'F08', 'F10', 'F12', 'F16' ) THEN ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'BACK_LEND_DIRECTION' AND ITEM_CODE = eted.BUSI_PS ) ELSE ( SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'PS' AND ITEM_CODE = ete.PS ) END AS otherPs, T4.TARGET_FINPROD_ID targetFinprodId, NVL ( T5.FINPROD_ABBR, T5.FINPROD_NAME ) targetFinprodName, mci2.CALENDAR_NAME calendarName, to_char( eted.VDATE, 'yyyy-MM-dd' ) vDate, to_char( eted.MDATE , 'yyyy-MM-dd' ) mDate, eted.MIN_AMT minAmt, eted.ASSET_TYPE1 paBussType, ete.portfolio_id portfolioId, pp.portfolio_name portfolioName, ete.inv_aim busiModel, fp.finprod_market_id finprodMarketId, fp.finprod_abbr finprodAbbr, ete.trade_market tradeMarket, ete.ps ps, DECODE(eted.SETTLE_SPREED,0,'01',1,'02','2','03') settleSpeed, ete.price_model priceModel, ssai.sec_acct_name secAcctId, ete.ccy ccy, decode( eted.ASSET_TYPE, 'F01', NVL( ete.ENTRUST_NUM * 100, 0 ), 'F10', NVL( ete.ENTRUST_NUM * 100, 0 ), NVL( ete.ENTRUST_AMT, ete.ENTRUST_NUM )) shareNum, eted.our_ent_num/100 entrustOwnNum, eted.lendin_ent_num integrateSecAmount, ete.price unitPrice, eted.full_price allPrice, eted.mature_yield*100 matureYield, eted.exer_yield*100 exerYield, eted.full_price*ete.entrust_num fpriceAmt, ete.remark remark, mci.CUSTOMER_NAME mainConsignee, to_char(eted.payment_date,'yyyy-MM-dd') paymentDate, to_char(eted.listing_date,'yyyy-MM-dd') listingDate, ete.entrust_num entrustNum, ete.entrust_amt entrustAmt, eted.deal_mode dealMode, eted.term_type termType, decode( eted.ASSET_TYPE, 'F01', '', 'F07', eted.TERM_DAYS, 'F10', eted.TERM_DAYS, 'F12', eted.TERM_DAYS, 'F16', eted.TERM_DAYS, eted.TERM_DAYS ) termDays, to_char(eted.MDATE,'yyyy-MM-dd') || ' - ' || to_char(eted.MDATE2,'yyyy-MM-dd') as dueDate, eted.TERM_DAYS repoTerm, eted.FIRST_UNIT_CPRICE || ' - ' || eted.FIRST_UNIT_CPRICE2 firstprice, pss.pledge_stock_name pledgeStockName, fp.Is_Right isRight, ete.PRICE * 100 rate FROM WFL_ETR_ENTRUST ete INNER JOIN WFL_ETR_ENTRUST_ADD eted ON ete.entrust_id = eted.entrust_id LEFT JOIN PTL_PORTFOLIO pp ON ete.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON ete.finprod_id = fp.finprod_id LEFT JOIN PTL_SEC_STOCK pss ON pss.pledge_stock_id = eted.pledge_stock_id AND ete.portfolio_id = pss.portfolio_id LEFT JOIN MST_CUSTOMER_INFO mci ON mci.CUSTOMER_ID = eted.main_consignee AND mci.IS_SALER = #{YESORNO_YES, jdbcType = VARCHAR} LEFT JOIN STL_SEC_ACCT_INFO ssai ON eted.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN ETR_TARGET T4 ON ete.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN FIN_PRODUCT T5 ON T4.TARGET_FINPROD_ID = T5.FINPROD_ID LEFT JOIN MST_CALENDAR_INFO mci2 ON mci2.CALENDAR_ID = ete.CALENDAR_ID WHERE ete.entrust_id = #{entrustId}

SELECT distinct decode(tpd.is_cancel,'Y',#{TRADE_FLOW_STATUS03},#{TRADE_FLOW_STATUS02}) effectFlag,
FROM trd_product_deal tpd LEFT JOIN trd_product_deal_add tpda ON tpd.trade_id = tpda.trade_id left join TRD_FIN_PRODUCT_DEAL_TOTAL tpdt on tpd.TOTLE_TRADE_ID=tpdt.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO pp ON tpda.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON tpd.finprod_id = fp.finprod_id LEFT JOIN MST_COUNTER_PARTY mcp ON tpd.counter_id = mcp.counter_id LEFT JOIN TRD_TRADE_FEE_DETAIL ttft ON tpd.trade_id = ttft.trade_id AND ttft.fee_type =#{feeType06} LEFT JOIN TRD_TRADE_FEE_DETAIL ttft1 ON tpd.trade_id = ttft1.trade_id AND ttft1.fee_type =#{feeType08} LEFT JOIN STL_SEC_ACCT_INFO ssai ON tpd.sec_manage_acct_id = ssai.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON (case when tpd.IS_OUT_TRADE='N' and tpd.R_TRADE_ID is not null then tpd.R_TRADE_ID else tpd.TRADE_ID end) = fpt.FINPROD_ID left join FIN_TRADE_PRODUCT FTP on (CASE WHEN tpd.IS_OUT_TRADE = 'N' AND tpd.SPLIT_TRADE_ID IS NOT NULL THEN tpd.SPLIT_TRADE_ID ELSE tpd.TRADE_ID END) = FTP.FINPROD_ID left join FIN_DEAL_PLEDGE on (CASE WHEN tpd.IS_OUT_TRADE = 'N' AND tpd.SPLIT_TRADE_ID IS NOT NULL THEN tpd.SPLIT_TRADE_ID ELSE tpd.TRADE_ID END) = FIN_DEAL_PLEDGE.FINPROD_ID LEFT JOIN FIN_PRODUCT fp2 ON fp2.FINPROD_ID = tpd.CHL_ID WHERE tpda.entrust_id = #{entrustId}
union all
SELECT #{TRADE_FLOW_STATUS01} effectFlag,
FROM wfl_trd_product_deal tpd LEFT JOIN wfl_trd_product_deal_add tpda ON tpd.trade_id = tpda.trade_id left join WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tpdt on tpd.TOTLE_TRADE_ID=tpdt.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO pp ON tpda.portfolio_id = pp.portfolio_id LEFT JOIN FIN_PRODUCT fp ON tpd.finprod_id = fp.finprod_id LEFT JOIN MST_COUNTER_PARTY mcp ON tpd.counter_id = mcp.counter_id LEFT JOIN TRD_TRADE_FEE_DETAIL ttft ON tpd.trade_id = ttft.trade_id AND ttft.fee_type =#{feeType06} LEFT JOIN TRD_TRADE_FEE_DETAIL ttft1 ON tpd.trade_id = ttft1.trade_id AND ttft1.fee_type =#{feeType08} LEFT JOIN STL_SEC_ACCT_INFO ssai ON tpd.sec_manage_acct_id = ssai.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON (case when tpd.IS_OUT_TRADE='N' and tpd.R_TRADE_ID is not null then tpd.R_TRADE_ID else tpd.TRADE_ID end) = fpt.FINPROD_ID left join FIN_TRADE_PRODUCT FTP on (CASE WHEN tpd.IS_OUT_TRADE = 'N' AND tpd.SPLIT_TRADE_ID IS NOT NULL THEN tpd.SPLIT_TRADE_ID ELSE tpd.TRADE_ID END) = FTP.FINPROD_ID left join FIN_DEAL_PLEDGE on (CASE WHEN tpd.IS_OUT_TRADE = 'N' AND tpd.SPLIT_TRADE_ID IS NOT NULL THEN tpd.SPLIT_TRADE_ID ELSE tpd.TRADE_ID END) = FIN_DEAL_PLEDGE.FINPROD_ID LEFT JOIN FIN_PRODUCT fp2 ON fp2.FINPROD_ID = tpd.CHL_ID WHERE tpda.entrust_id = #{entrustId}

